import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.DomDLpZJ.js";const u=JSON.parse('{"title":"Compared with other setups","description":"","frontmatter":{},"headers":[],"relativePath":"guide/comparison.md","filePath":"guide/comparison.md","lastUpdated":1794409460000}'),s={name:"guide/comparison.md"};function i(d,e,n,h,l,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="compared-with-other-setups" tabindex="-1">Compared with other setups <a class="header-anchor" href="#compared-with-other-setups" aria-label="Permalink to &quot;Compared with other setups&quot;">​</a></h1><p>ktor-svelte is one way to put a Ktor API and a SvelteKit frontend together. This page compares it with the common alternatives, so you can tell whether it fits before you start.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>ktor-svelte</th><th>SvelteKit <code>adapter-node</code> in front of Ktor</th><th>Static frontend on a CDN, Ktor API elsewhere</th><th>Ktor <code>staticResources</code> by hand</th></tr></thead><tbody><tr><td>Processes in production</td><td>1 JVM</td><td>Node and JVM</td><td>JVM, plus the CDN</td><td>1 JVM</td></tr><tr><td>Origins</td><td>One</td><td>One, through the Node server</td><td>Two, so CORS</td><td>One</td></tr><tr><td>Server-side rendering per request</td><td>No, prerendering at build time</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Typed client for your Ktor routes</td><td>Generated</td><td>Write or generate it yourself</td><td>Write or generate it yourself</td><td>Write or generate it yourself</td></tr><tr><td>SPA fallback, trailing slashes, stale chunk 404s</td><td>Built in</td><td>Built in</td><td>CDN rules</td><td>Write them yourself</td></tr><tr><td>Caching headers, ETags, precompressed files</td><td>Built in</td><td>Built in for assets</td><td>CDN</td><td>Partly, configure yourself</td></tr><tr><td>Dev loop</td><td>One command, hot reload on Ktor&#39;s port</td><td>Two servers, proxy config</td><td>Two servers, CORS in dev</td><td>Rebuild the frontend or run two servers</td></tr><tr><td>Deploy</td><td>One JAR</td><td>Two artifacts</td><td>Two artifacts</td><td>One JAR</td></tr></tbody></table><h2 id="sveltekit-with-adapter-node-in-front-of-ktor" tabindex="-1">SvelteKit with <code>adapter-node</code> in front of Ktor <a class="header-anchor" href="#sveltekit-with-adapter-node-in-front-of-ktor" aria-label="Permalink to &quot;SvelteKit with `adapter-node` in front of Ktor&quot;">​</a></h2><p>SvelteKit runs as its own Node server, renders pages per request, and calls Ktor from <code>+page.server.ts</code> or forwards <code>/api</code> to it.</p><p>Pick this when you need per-request server-side rendering: pages with personal data that search engines must see, or first paint from data that changes on every request. You also get <code>+server.ts</code> endpoints and form actions.</p><p>The cost is two runtimes to deploy, monitor and scale, auth that has to work in both, and a hop between them. With ktor-svelte, prerendered pages cover content known at build time, and pages that need API data render in the browser. The <a href="./../reference/faq">FAQ</a> explains this choice in more detail.</p><h2 id="a-static-frontend-on-a-cdn-with-a-separate-ktor-api" tabindex="-1">A static frontend on a CDN with a separate Ktor API <a class="header-anchor" href="#a-static-frontend-on-a-cdn-with-a-separate-ktor-api" aria-label="Permalink to &quot;A static frontend on a CDN with a separate Ktor API&quot;">​</a></h2><p>The frontend is built with <code>adapter-static</code> and uploaded to a CDN or object storage, and the browser calls Ktor on another domain.</p><p>Pick this when the frontend has a very high share of traffic, or a team that deploys it on its own schedule. The CDN serves files from close to the user.</p><p>The cost is two deployments that must stay compatible, CORS and its preflight requests, and cookies that need <code>SameSite=None</code> or a shared parent domain. ktor-svelte keeps one origin, so cookies and the origin check work without extra configuration. You can still put a CDN in front of the single app: hashed files under <code>/_app/immutable/</code> are marked cacheable forever.</p><h2 id="ktor-serving-the-build-with-staticresources" tabindex="-1">Ktor serving the build with <code>staticResources</code> <a class="header-anchor" href="#ktor-serving-the-build-with-staticresources" aria-label="Permalink to &quot;Ktor serving the build with `staticResources`&quot;">​</a></h2><p>You copy the SvelteKit build into your resources yourself and serve it with Ktor&#39;s static content support.</p><p>This works for a small app with only a few pages. Everything ktor-svelte adds is left to you: wiring the frontend build into Gradle, the SPA fallback that does not swallow API 404s, redirects for trailing slashes, real 404s for missing chunks after a deploy, precompressed files, CSP hashes for SvelteKit&#39;s inline scripts, the dev proxy and the TypeScript client.</p><h2 id="other-full-stack-frameworks" tabindex="-1">Other full-stack frameworks <a class="header-anchor" href="#other-full-stack-frameworks" aria-label="Permalink to &quot;Other full-stack frameworks&quot;">​</a></h2><ul><li><strong>Spring Boot with a frontend build plugin</strong> follows the same idea on Spring. ktor-svelte is the Ktor and SvelteKit version, with the generated client and dev proxy included.</li><li><strong>Kotlin frontend frameworks</strong>, such as Compose for Web or Kobweb, share one language across the stack. ktor-svelte keeps the frontend in TypeScript and Svelte, and shares types through the generated client instead.</li><li><strong>JavaScript full-stack frameworks</strong>, such as SvelteKit on its own, Next.js or Nuxt, keep everything in one JavaScript runtime. Choose ktor-svelte when the backend is, or should be, on the JVM.</li></ul><h2 id="when-ktor-svelte-is-not-the-right-fit" tabindex="-1">When ktor-svelte is not the right fit <a class="header-anchor" href="#when-ktor-svelte-is-not-the-right-fit" aria-label="Permalink to &quot;When ktor-svelte is not the right fit&quot;">​</a></h2><ul><li>You need server-side rendering on every request.</li><li>The frontend and the backend are deployed by different teams on different schedules.</li><li>The app mounts under a sub-path, which ktor-svelte does not support yet.</li><li>You want SvelteKit&#39;s <code>+page.server.ts</code>, <code>+server.ts</code> or form actions. In ktor-svelte, Ktor routes take their place.</li></ul>',19)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
